<p><span style="text-decoration: underline;"><strong>Priority</strong></span></p>
<p>&nbsp;</p>
<p>#include&lt;stdio.h&gt;<br />main()<br />{<br />int p[20],bt[20],pri[20], wt[20],tat[20],i, k, n, temp;<br />float wtavg, tatavg;<br />clrscr();<br />printf("Enter the number of processes --- ");<br />scanf("%d",&amp;n);<br />for(i=0;i&lt;n;i++)<br />{<br />p[i] = i;<br />printf("Enter the Burst Time &amp; Priority of Process %d --- ",i);<br />scanf("%d %d",&amp;bt[i], &amp;pri[i]);<br />}<br />for(i=0;i&lt;n;i++)<br />for(k=i+1;k&lt;n;k++)<br />if(pri[i] &gt; pri[k])<br />{<br />temp=p[i];<br />p[i]=p[k];<br />p[k]=temp;<br />temp=bt[i];<br />bt[i]=bt[k];<br />bt[k]=temp;<br />temp=pri[i];<br />pri[i]=pri[k];<br />pri[k]=temp;<br />}<br />wtavg = wt[0] = 0;<br />tatavg = tat[0] = bt[0];<br />for(i=1;i&lt;n;i++)<br />{<br />wt[i] = wt[i-1] + bt[i-1];<br />tat[i] = tat[i-1] + bt[i];<br />wtavg = wtavg + wt[i];<br />tatavg = tatavg + tat[i];<br />}<br />printf("\nPROCESS\t\tPRIORITY\tBURST TIME\tWAITING TIME\tTURNAROUND TIME");<br />for(i=0;i&lt;n;i++)<br />printf("\n%d \t\t %d \t\t %d \t\t %d \t\t %d ",p[i],pri[i],bt[i],wt[i],tat[i]);<br />printf("\nAverage Waiting Time is --- %f",wtavg/n);<br />printf("\nAverage Turnaround Time is --- %f",tatavg/n);<br />getch();<br />}</p>